head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil70701";
scwin.form = null;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_rowCopy();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil70701.onpageload' });
    }
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "__rb0", fn: function () { return "전체 " + String(dma_page.get("total")) + "건 (" + String(dma_page.get("currentPage")) + "/" + String(dma_page.get("pageCount")) + " 페이지)"; } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

// [A] 초기 목록 미해결 — jldfil70701: 진입 키 etnsrtymng 는 알지만 그 URL 을 쓰는 tx 가 화면에 없다(URL 을 지어내지 않는다) · 자기 목록 tx 0

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name grd_pageList_oncellclick
 * @description grd_pageList 셀 클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_pageList_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_pageList');
        if (!dl) { /* TODO Stage2: [sdd] 행 동작 대상 목록 없음: dlt_pageList */ return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        await scwin.viewEtnSrty("VIEW", r["srtyCd"]); return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_pageList.oncellclick' });
    }
};

/**
 * @method
 * @name btn_ViewEtnSrty_2_onclick
 * @description 「신규등록신청」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_ViewEtnSrty_2_onclick = async function(e){
    try {
        await scwin.viewEtnSrty('NEW','')

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil70701.btn_ViewEtnSrty_2_onclick' }); }
};

/**
 * @method
 * @name krxpage_pagenavigator_41_onclick
 * @description krxpage_pagenavigator_41 클릭 이벤트
 * @param {Number} index index
 * @returns {void}
 * @hidden N
 */
scwin.krxpage_pagenavigator_41_onclick = function (index) { const pi = (index && typeof index === 'object') ? index.newSelectedIndex : index; try { $c.util.getComponent('dma_ViewEtnSrtyReq').set('pageIndex', pi); } catch (e) { $c.exception.handleError(e, { notify: 'none', context: 'krxpage_pagenavigator_41.page' }); } scwin.search(); };

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_ViewEtnSrty
 * @description View Etn Srty 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_ViewEtnSrty = async function () {
    const sbmOptions = {
        id: "tx_fn_ViewEtnSrty",
        method: "post",
        action: "/etn/EtnSrtyMng.do",
        ref: "dma_ViewEtnSrtyReq",
        target: "dlt_pageList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name search
 * @description search 처리
 * @returns {void}
 * @hidden N
 */
scwin.search = function () {
    scwin.form = (document.etnSrtyForm || { elements: [] });
    $c.util.getComponent('dma_ViewEtnSrtyReq').set('method', 'searchEtnSrty');
    scwin.form.submit();
};

/**
 * @method
 * @name viewEtnSrty
 * @description view Etn Srty 처리
 * @param {String} flag flag
 * @param {String} srtyCd srtyCd
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.viewEtnSrty = async function (flag, srtyCd) {
    scwin.form = (document.etnSrtyForm || { elements: [] });
    $c.util.getComponent('dma_ViewEtnSrtyReq').set('formGubun', flag);
    $c.util.getComponent('dma_ViewEtnSrtyReq').set('srtyCd', srtyCd);
    $c.util.getComponent('dma_ViewEtnSrtyReq').set('method', 'viewEtnSrty');
    scwin.form.action = "EtnSrtyMng.do";
    const nr = await scwin.tx_fn_ViewEtnSrty();
    if (nr && nr.responseJSON && nr.responseJSON.success === true) {
        $c.win.moveUrl("/jldfil70702/jldfil70702.xml", { "formGubun": flag, "srtyCd": srtyCd, "method": 'viewEtnSrty' });
    }
};
